from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    color = min((v for v in counts if v != 0), key=lambda v: counts[v])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0, c0 = min(r for r, c in cells), min(c for r, c in cells)
    mask = [(r-r0, c-c0) for r, c in cells]
    mh, mw = max(r for r, c in mask)+1, max(c for r, c in mask)+1
    out = [row[:] for row in grid]
    for top in range(h-mh+1):
        for left in range(w-mw+1):
            if all(grid[top+dr][left+dc] == 0 for dr, dc in mask):
                for dr, dc in mask:
                    out[top+dr][left+dc] = color
    return out

